          "distinct": true,
          "id": "cf55f8f11a7ff46d4d08b49c6e83a552c023b06d",
          "message": "docs(readme): broaden FMA guide beyond `-Ctarget-cpu=native`\n\n- Note that AArch64, RISC-V Zfa and wasm relaxed-simd already enable FMA,\n  so the warning is x86-64-specific.\n- Recommend `-Ctarget-cpu=x86-64-v3` as the portable default (AVX2 + FMA,\n  runs on every modern x86-64) and scope the per-project snippet to\n  `cfg(target_arch = \"x86_64\")` so it's harmless in cross builds.\n- Mention the `~/.cargo/config.toml` and `RUSTFLAGS=\\u2026` alternatives.\n- Keep `-Ctarget-cpu=native` as the opt-in for max local perf and warn\n  about the SIGILL trap when sharing the resulting binary.",
          "timestamp": "2026-06-02T00:49:19+08:00",
          "tree_id": "e6f18359ca7d4cac77c164d4b8a5a0f640b3e702",
