          "distinct": true,
          "id": "e9e392f971aa315f2fec370757c4ad70df87fecc",
          "message": "Speed up f32 cosh with addition formula, reusing SINH_CORE / COSH_CORE\n\nApply the same approach as the sinh change: replace finite_exp(x) +\ny.recip() with the addition formula\n\n  cosh(n·ln2 + r) = cosh(n·ln2)·cosh(r) + sinh(n·ln2)·sinh(r)\n\nusing the SINH_CORE and COSH_CORE polynomials already introduced by the\nsinh commit.  Eliminates the only remaining division on the hyperbolic\nmain path.\n\nCo-Authored-By: Claude Sonnet 4.6 <noreply@anthropic.com>",
          "timestamp": "2026-06-02T15:08:33+08:00",
          "tree_id": "b7e913b9859328e359002a75abcfe61e254ab0c3",
          "url": "https://github.com/jdh8/metallic-rs/commit/e9e392f971aa315f2fec370757c4ad70df87fecc"
