          "distinct": false,
          "id": "d39aa96daccde60a736046191c0d694789d8906f",
          "message": "Speed up f32 powf with a fast f64 path and Ziv fallback\n\nThe always-double-double powf was correct but ~4× slower than CORE-MATH,\nsince the DD log2/exp2 ran on every input.  Add an f64 fast path and keep\nthe DD path only as a fallback:\n\n- `log2_fast` / `EXP2_FAST` / `LOG2_FAST`: plain-f64 degree-10 minimax\n  versions of the log2 and exp2 kernels.\n- `powf_core`: computes `2^(y·log₂x)` in f64.  The result is good to\n  ≈2⁻⁴⁵ relative and `2^E` never cancels, so the exp_m1-style integer\n  midpoint test applies directly: if the discarded low 29 bits clear the\n  round-to-nearest midpoint by `0x2000` (≈2⁻³⁹, well above the error) and\n  the value is in the normal f32 range, the single rounding is returned.\n  Otherwise — the few ambiguous roundings plus the subnormal / near-\n  overflow ends, where the bit test does not apply — it falls back to the\n  double-double `log2_dd → ×y → exp2_dd` path.\n\nStill matches CORE-MATH on all 133 216 `powf.wc` cases and 300M random\npairs, so correct rounding is preserved.  ~84 → ~20.8 ns, now a touch\nfaster than CORE-MATH (~21.8 ns).\n\nCo-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>",
          "timestamp": "2026-06-02T18:06:44+08:00",
          "tree_id": "d7709282cbc9e659c57fb69c22349c6b3b600dbc",
