          "distinct": true,
          "id": "7f5eccb1ace2091a8045e9fcf7df15d7f99faf1a",
          "message": "Document bivariate hard-to-round case search in the skill\n\nAdd a section to the program-math-functions skill (correct-rounding.md) on\ngenerating worst cases when no published table exists, drawn from the\nCORE-MATH paper: it frames the random-MPFR-scan corpus as the \"naive search\"\nand documents the structured alternatives — Algorithm 1 (fix one argument,\ndegree-2 Taylor, finite-differences evaluation mod 2^64, ~17x faster than\nBaCSeL), the inverse-function trick, the number-theoretic shortcuts for\nhypot (almost-Pythagorean triples) and atan2 (continued-fraction convergents\nof tan z), midpoint/exact enumeration, the complex -> bivariate-components\nreduction, and the BaCSeL/SLZ tooling.\n\nCo-Authored-By: Claude Opus 4.8 <noreply@anthropic.com>",
          "timestamp": "2026-06-03T15:06:35+08:00",
