          "distinct": true,
          "id": "5001ef83da63608cb90fbb6c6c68541bbbf72ebf",
          "message": "Give f64 exp_m1's table branch the two-level lean fast leg\n\n`exp_m1`'s `n ≠ 0` path took its `eˣ` mantissa from `exp_mantissa_fast`\n(N=128).  Route it through `exp_two_level_fast` so it inherits the finer grid\nand lean fold, gating `2^q·m − 1` at `2^q · EXP_TWO_LEVEL_ZIV_EPS` — the leg's\n≈2⁻⁶⁴ mantissa error scales to `2^q·2⁻⁶⁴` on the result, inside the 2⁻⁶²\nbudget.  The N=128 reduction is now built only on the (rare) accurate\nfallback, and the small-`|x|` `S(x)` branch is untouched.\n\nBit-exact vs CORE-MATH over the dense + bit-pattern sweep.  exp_m1 12.4 → 10.8\nns (1.27 → 1.11× CM); now beats std (12.9) and libm (13.4).  Part of issue #5\n(#1 cascade).\n\nCo-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>",
          "timestamp": "2026-06-06T06:51:34+08:00",
          "tree_id": "d29428145f26b04e4db27997e002c03dde3b8db7",
          "url": "https://github.com/jdh8/metallic-rs/commit/5001ef83da63608cb90fbb6c6c68541bbbf72ebf"
